WITH valid AS (SELECT *, ROUND(pressure * 0.9, 2) AS pressure_adjusted FROM device_readings WHERE reading_ts >= TO_DATE('2025-09-01') AND firmware = '1.0.3'), flagged AS (SELECT *, CASE WHEN LAG(reading_ts) OVER (PARTITION BY device_code ORDER BY reading_ts, id) IS NULL OR reading_ts > LAG(reading_ts) OVER (PARTITION BY device_code ORDER BY reading_ts, id) + INTERVAL 30 MINUTES THEN 1 ELSE 0 END AS session_start_flag FROM valid), sessions_device_readings AS (SELECT *, SUM(session_start_flag) OVER (PARTITION BY device_code ORDER BY reading_ts, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS burst_id FROM flagged) SELECT CASE WHEN session_start_flag >= 1 THEN 'LARGE' ELSE 'SMALL' END AS session_start_flag_tier, ROUND(AVG(session_start_flag), 2) AS avg_session_start_flag, COUNT(*) FILTER (WHERE device_code = 'DV-02') AS dv_02_rows, COUNT(DISTINCT id) AS distinct_ids, SIZE(COLLECT_SET(device_code)) AS num_device_codes, SUM(status_bits) FILTER (WHERE device_code = 'DV-03') AS dv_03_total_status_bits, MAX(reading_ts) AS last_seen FROM sessions_device_readings GROUP BY session_start_flag_tier HAVING ROUND(AVG(session_start_flag), 2) > 0 ORDER BY session_start_flag_tier DESC
